CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'STUDENT', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materials (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, file_name VARCHAR(255) NOT NULL, storage_key VARCHAR(80) NOT NULL UNIQUE, mime_type VARCHAR(120) NOT NULL, file_size BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'UPLOADED', extracted_text TEXT, summary TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_material_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_material_owner(owner_id));
